  limit: '10kb' // Prevent large payload attacks
}));

// Validate content type
app.use((req, res, next) => {
  // If content-type is present, verify it's application/json
  const contentType = req.get('Content-Type');
  if (contentType && !contentType.includes('application/json')) {
    return res.status(400).json({
      error: 'Invalid Content-Type. Expected application/json'
    });
  }
  next();
});

// Rate limiting to prevent abuse (basic implementation)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
const MAX_REQUESTS = 100; // Max requests per window

app.use((req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  // Clean old entries
  for (const [requestIp, data] of requestCounts) {
    if (now - data.timestamp > RATE_LIMIT_WINDOW) {
      requestCounts.delete(requestIp);
    }
  }

  // Check rate limit
  const requestData = requestCounts.get(ip) || { count: 0, timestamp: now };

  if (requestData.count >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Rate limit exceeded. Please try again later.'
    });
