// 6. Prevent parameter pollution
app.use(hpp());

// 7. Custom middleware for request logging (development)
if (process.env.NODE_ENV === 'development') {
  app.use((req, res, next) => {
    req.requestTime = new Date().toISOString();
    console.log(req.method, req.url);
    next();
  });
}

// Health endpoint with improved error handling
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters if any
    const { verbose } = req.query;

    // Basic validation
    if (verbose && typeof verbose !== 'string') {
      return next(new AppError('Verbose parameter must be a string', 400));
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    // Add verbose information if requested
    if (verbose === 'true') {
      healthData.process = {
        memory: process.memoryUsage(),
        nodeVersion: process.version,
      };
    }

    res.json(healthData);
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

